import type { BankQuestion } from "@/lib/bank";

/** Ecology and Environment (Biology (NEET)): 134 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-ecology-environment-1","question":"Which ecological pyramid can NEVER be inverted?","options":["Pyramid of numbers","Pyramid of biomass","Pyramid of energy","Pyramid of species"],"answer":2,"explanation":"Energy decreases at each successive trophic level (only about 10% is transferred), so the pyramid of energy is always upright. Pyramids of numbers (a tree) and biomass (sea) can be inverted.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-2","question":"In a grazing food chain, herbivores occupy the trophic level of:","options":["Producers","Primary consumers","Secondary consumers","Decomposers"],"answer":1,"explanation":"Producers (plants) are at the first trophic level; herbivores that eat them are primary consumers (second trophic level); carnivores eating herbivores are secondary consumers.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-3","question":"The thinning of the stratospheric ozone layer is chiefly caused by:","options":["Chlorofluorocarbons (CFCs)","Carbon dioxide (CO₂)","Sulphur dioxide (SO₂)","Methane from flooded paddy fields"],"answer":0,"explanation":"CFCs from refrigerants and aerosols reach the stratosphere, where UV releases chlorine atoms that break down ozone catalytically. The ozone hole over Antarctica is the best-known result.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-4","question":"In the logistic growth equation dN/dt = rN[(K − N)/K], the symbol K stands for:","options":["Intrinsic rate of natural increase","Number of deaths per unit time","Population density at time zero","Carrying capacity of the habitat"],"answer":3,"explanation":"K is the carrying capacity: the maximum population a habitat can support with its limited resources. r is the intrinsic rate of natural increase and N the population density at time t.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-5","question":"The relationship between a fig tree and its pollinating wasp species, in which the wasp lays eggs in the fig fruit and pollinates the flowers, is an example of:","options":["Commensalism","Parasitism","Mutualism","Amensalism"],"answer":2,"explanation":"Both benefit: the wasp uses the fruit as an oviposition site and larval food, while the fig depends on the wasp for pollination. Each fig species has its own wasp species (co-evolution).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-6","question":"If producers in an ecosystem trap 1000 J of energy, the energy available to secondary consumers, according to Lindeman’s 10% law, is about:","options":["10 J","100 J","1 J","500 J"],"answer":0,"explanation":"Only 10% of the energy of a trophic level passes to the next: primary consumers get 100 J, secondary consumers get 10 J and tertiary consumers 1 J.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-7","question":"Which of the following biodiversity hotspots does NOT cover any part of India?","options":["Western Ghats and Sri Lanka","Indo-Burma","Himalaya","Sundaland"],"answer":3,"explanation":"Of the 34 hotspots, three (Western Ghats and Sri Lanka, Indo-Burma, Himalaya) include regions of India with exceptionally high biodiversity. Sundaland covers Malaysia and Indonesia.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-8","question":"The Montreal Protocol, signed in 1987 and effective from 1989, aims to:","options":["Reduce emissions of greenhouse gases","Conserve wetlands of international importance","Phase out ozone-depleting substances","Reduce the rate of biodiversity loss by 2010"],"answer":2,"explanation":"The Montreal Protocol is the international agreement to phase out ozone-depleting substances such as CFCs. Reduction of biodiversity loss was the goal set at the 2002 Johannesburg summit.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-9","question":"Biochemical oxygen demand (BOD) of a water sample is a measure of:","options":["The dissolved oxygen already present in the water","Oxygen microbes need to break down organic matter","The oxygen released by phytoplankton in a day","The amount of heavy metals and toxins present"],"answer":1,"explanation":"A high BOD means heavy organic pollution (such as sewage): microbes consuming it deplete dissolved oxygen, which can kill fish and other aquatic life.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-10","question":"An urn-shaped age pyramid, with few pre-reproductive individuals, indicates a population that is:","options":["Expanding","Stable","Declining","Fluctuating seasonally"],"answer":2,"explanation":"A triangular (broad base) pyramid is an expanding population, a bell shape is stable, and an urn shape with a narrow base of young individuals is a declining population.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-11","question":"The annual net primary productivity of the whole biosphere is about 170 billion tons (dry weight) of organic matter. The share of the oceans, despite covering about 70% of the surface, is only about:","options":["115 billion tons","85 billion tons","55 billion tons","17 billion tons"],"answer":2,"explanation":"Oceans contribute only about 55 billion tons of the 170 billion tons because light and nutrients limit production in most of the sea; land contributes the remaining 115 billion tons.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-12","question":"Connell’s field experiments on the rocky sea coasts of Scotland with the barnacles Balanus and Chthamalus demonstrated:","options":["Interspecific competition: Balanus excludes Chthamalus","Mutualism, both barnacles sharing the same rock surface","Predation by the larger Balanus on Chthamalus","Resource partitioning, as in MacArthur's warblers"],"answer":0,"explanation":"The larger Balanus dominates the intertidal zone and excludes the smaller Chthamalus from it; Chthamalus survives only in the upper zone where Balanus cannot. This is competitive release/exclusion, not predation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-13","question":"In the species–area relationship log S = log C + Z log A, the value of Z for small areas such as a region or country generally lies between:","options":["0.6 and 1.2","0.1 and 0.2","1 and 2","0.01 and 0.05"],"answer":1,"explanation":"The slope Z of the regression is 0.1–0.2 regardless of the taxonomic group or region for small areas; for very large areas such as entire continents Z becomes 0.6–1.2 (steeper).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-14","question":"During decomposition, the step in which bacterial and fungal enzymes degrade detritus into simpler inorganic substances is called:","options":["Fragmentation","Leaching","Catabolism","Humification"],"answer":2,"explanation":"Fragmentation is done by detritivores (e.g. earthworms), leaching removes soluble nutrients into the soil, catabolism is enzymatic degradation, humification forms humus and mineralisation finally releases inorganic nutrients.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-15","question":"Sacred groves, tracts of forest protected by religious tradition, are found in all of the following EXCEPT:","options":["Khasi and Jaintia hills of Meghalaya","Aravalli hills of Rajasthan","Sundarbans of West Bengal","Sarguja, Chanda and Bastar areas of Madhya Pradesh"],"answer":2,"explanation":"NCERT lists sacred groves in Meghalaya, Rajasthan’s Aravallis, the Western Ghats of Karnataka and Maharashtra, and the Sarguja, Chanda and Bastar areas of Madhya Pradesh. The Sundarbans is a protected mangrove area, not a sacred grove.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-16","question":"Which statement about the phosphorus cycle is correct?","options":["It has a significant gaseous phase in the atmosphere","Its atmospheric input by rainfall exceeds that of carbon","Respiration releases much phosphorus to the air","Its natural reservoir is phosphate-containing rock"],"answer":3,"explanation":"Phosphorus is a sedimentary cycle: weathering of phosphate rocks releases it to soil, plants absorb it, and decomposers return it. Unlike carbon, it has no respiratory release to the atmosphere and negligible atmospheric input.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-17","question":"In a classic case of biomagnification, DDT at about 0.003 ppb in water rose to about 25 ppm in fish-eating birds. This happened because DDT:","options":["Is not metabolised or excreted, so it builds up at each level","Is water soluble, so birds drink more of it than fish","Is broken down by fish into more toxic and persistent products","Is produced naturally by phytoplankton in the lake"],"answer":0,"explanation":"Substances that are not metabolised or excreted increase in concentration up the food chain. In birds high DDT disturbs calcium metabolism, thinning eggshells and causing premature breaking.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-18","question":"Mammals living in colder climates generally have shorter ears and limbs to reduce heat loss. This generalisation is called:","options":["Gause’s principle","Allen’s rule","Lindeman’s law","Verhulst–Pearl law"],"answer":1,"explanation":"Allen’s rule concerns body extremities and heat loss. Gause’s is the competitive exclusion principle; Lindeman gave the 10% law; Verhulst–Pearl describes logistic growth.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-19","question":"How many of the following statements about population interactions are correct?\n(i) An orchid growing on a mango branch is commensalism (+, 0).\n(ii) Amensalism is an interaction in which one species is harmed and the other is unaffected.\n(iii) Both predation and parasitism are (+, 0) interactions.\n(iv) Competition occurs only between closely related species.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(i) and (ii) are correct. (iii) is wrong: predation and parasitism are (+, −) interactions, since one species benefits at the other's cost. (iv) is wrong: totally unrelated species can also compete, e.g. flamingoes and fishes for zooplankton.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-20","question":"Match the conservation effort with its description.\nA. Chipko movement — 1. Villagers of Garhwal Himalaya hugged trees to protect them from contractors’ axes, 1974\nB. Amrita Devi Bishnoi — 2. 365 persons sacrificed their lives to protect trees in Jodhpur, 1731\nC. Joint Forest Management — 3. Government of India involved local communities in protecting degraded forests, from 1980s\nD. Delhi vehicular pollution — 4. Switching the whole public transport fleet to CNG by the end of 2002","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-3, C-2, D-4","A-1, B-2, C-4, D-3"],"answer":0,"explanation":"Both the Bishnoi sacrifice (1731) and Chipko (1974) are community actions against tree felling; JFM gives communities a share in forest benefits; Delhi’s CNG switch was a court-directed pollution measure.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-21","question":"When the area sampled increases 100-fold, the number of species rises from 50 to 100. The value of Z in the species–area relationship S = CA^Z is:","options":["0.50","0.15","0.30","2.00"],"answer":1,"explanation":"S₂/S₁ = (A₂/A₁)^Z, so 2 = 100^Z and Z = log 2 / log 100 = 0.301/2 ≈ 0.15, in the 0.1–0.2 range typical of small areas. Forgetting to divide by log 100 = 2 gives the 0.30 trap.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-22","question":"A population growing logistically has r = 0.1 per year, carrying capacity K = 1000 and current size N = 500. Its instantaneous growth rate dN/dt is:","options":["50 per year","25 per year","100 per year","12.5 per year"],"answer":1,"explanation":"dN/dt = rN(K − N)/K = 0.1 × 500 × (500/1000) = 0.1 × 500 × 0.5 = 25 per year. Exponential growth at the same N would give 50, but the environmental resistance halves it.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-23","question":"Assertion (A): In the sea, the pyramid of biomass is generally inverted.\nReason (R): The standing crop of phytoplankton at a given time is small compared with that of the fish that feed on them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Phytoplankton have very short lives and high turnover, so their biomass at any instant is less than that of the longer-lived consumers, yet energy flow is still from phytoplankton upward and the energy pyramid remains upright.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-24","question":"How many of the following statements about global and Indian biodiversity are correct?\n(i) India has only 2.4% of the world’s land area but about 8.1% of the global species diversity.\n(ii) Among animals, insects are the most species-rich group, making up more than 70% of animal species.\n(iii) The number of fungal species in the world is more than the combined total of all vertebrate species.\n(iv) The Amazonian rain forest harbours about 1300 species of birds and more than 40,000 species of plants.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT data. The Amazon also has 3000 fishes, 427 mammals, 427 amphibians, 378 reptiles and over 125,000 invertebrates. Robert May’s estimate puts total global diversity at about 7 million species.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-25","question":"Match the cause of biodiversity loss with its example.\nA. Alien species invasion — 1. Steller’s sea cow and passenger pigeon hunted to extinction\nB. Over-exploitation — 2. Nile perch introduced into Lake Victoria wiped out over 200 species of cichlid fish\nC. Co-extinction — 3. Loss of a host fish species dooms its unique parasites\nD. Habitat loss and fragmentation — 4. Tropical rain forests reduced from 14% to 6% of the earth’s land surface","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-3, D-4","A-2, B-3, C-1, D-4","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"These four are the ‘Evil Quartet’ of biodiversity loss. Other alien invaders in NCERT are Parthenium, Lantana, Eichhornia and the African catfish Clarias gariepinus.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-26","question":"Which of the following is NOT a method of ex situ conservation?","options":["Zoological parks and botanical gardens","Cryopreservation of gametes of threatened species in liquid nitrogen","Seed banks and in vitro fertilisation","Biosphere reserves and national parks"],"answer":3,"explanation":"Ex situ methods conserve species outside their natural habitat (zoos, botanical gardens, seed banks, cryopreservation, tissue culture). Biosphere reserves, national parks and sanctuaries protect the whole ecosystem in situ.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-27","question":"How many of the following statements are correct?\n(i) The Earth Summit (Convention on Biological Diversity) was held at Rio de Janeiro in 1992.\n(ii) The World Summit on Sustainable Development at Johannesburg in 2002 pledged a significant reduction in the rate of biodiversity loss by 2010.\n(iii) The 34 biodiversity hotspots together cover less than 2% of the earth’s land area, yet their strict protection could reduce ongoing mass extinctions by almost 30%.\n(iv) According to NCERT, India has 14 biosphere reserves, 90 national parks and 448 wildlife sanctuaries.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four statements reproduce NCERT data on international and Indian conservation efforts. Hotspots are chosen for high species richness, high endemism and accelerated habitat loss.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-28","question":"How many of the following statements about control of air pollution are correct?\n(i) An electrostatic precipitator can remove over 99% of the particulate matter in exhaust from a thermal power plant.\n(ii) A scrubber removes gases like sulphur dioxide by passing the exhaust through a spray of water or lime.\n(iii) Catalytic converters contain platinum–palladium and rhodium, and vehicles fitted with them must use unleaded petrol since lead inactivates the catalyst.\n(iv) According to the CPCB, particulate matter of 2.5 micrometres or less in diameter (PM 2.5) is responsible for the greatest harm to human health.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT facts. In a catalytic converter unburnt hydrocarbons are converted into CO₂ and water, and CO and nitric oxide into CO₂ and nitrogen gas.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-29","question":"Arrange the greenhouse gases in decreasing order of their relative contribution to total global warming.","options":["CO₂ > CH₄ > CFCs > N₂O","CO₂ > CFCs > CH₄ > N₂O","CH₄ > CO₂ > N₂O > CFCs","CO₂ > N₂O > CH₄ > CFCs"],"answer":0,"explanation":"Relative contributions: CO₂ about 60%, methane 20%, CFCs 14% and N₂O 6%. Though CFCs are potent, their contribution is less than methane’s because of their low concentration.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-30","question":"In a grassland the gross primary productivity is 20,000 kcal m⁻² yr⁻¹ and the producers lose 12,000 kcal m⁻² yr⁻¹ in respiration. Assuming the 10% law, the energy available to the secondary consumers is approximately:","options":["200 kcal m⁻² yr⁻¹","80 kcal m⁻² yr⁻¹","800 kcal m⁻² yr⁻¹","2000 kcal m⁻² yr⁻¹"],"answer":1,"explanation":"NPP = GPP − R = 20,000 − 12,000 = 8000 kcal m⁻² yr⁻¹ available to herbivores’ trophic level. Primary consumers receive 10% = 800 and secondary consumers 10% of that = 80 kcal m⁻² yr⁻¹.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-31","question":"Primary productivity of an ecosystem is commonly expressed in units of:","options":["Number of species per hectare","Joules per second per individual","kg per individual","g m⁻² yr⁻¹ or kcal m⁻² yr⁻¹"],"answer":3,"explanation":"Primary productivity is the rate of biomass production per unit area over a time period, expressed as weight (g m⁻²) or energy (kcal m⁻²) per year.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-32","question":"The detritus food chain begins with:","options":["Herbivores grazing on green grass","Phytoplankton in the pond","Top carnivores at the apex","Dead organic matter (detritus)"],"answer":3,"explanation":"The DFC starts with detritus; decomposers (saprotrophs, mainly fungi and bacteria) secrete digestive enzymes and absorb the products. In terrestrial ecosystems a much larger fraction of energy flows through the DFC than the GFC.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-33","question":"The cuckoo laying its eggs in the nest of a crow and letting the crow incubate them is an example of:","options":["Mutualism (+, +)","Amensalism (−, 0)","Commensalism (+, 0)","Brood parasitism"],"answer":3,"explanation":"In brood parasitism the parasitic bird lays eggs in the host's nest; the cuckoo's eggs resemble the crow's in size and colour, reducing the chance of rejection.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-34","question":"A pond had 50 lotus plants last year; through reproduction 10 new plants were added. The birth rate of this population is:","options":["0.6 offspring per lotus per year","0.2 offspring per lotus per year","10 offspring per year","5 offspring per lotus per year"],"answer":1,"explanation":"Birth rate = number of births ÷ initial population = 10 ÷ 50 = 0.2 offspring per lotus per year.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-35","question":"The 'rivet popper' hypothesis, which compares species in an ecosystem to rivets in an aeroplane, was proposed by:","options":["David Tilman","Robert May","Alexander von Humboldt","Paul Ehrlich"],"answer":3,"explanation":"Paul Ehrlich used the analogy: losing a few rivets (species) may not harm the plane, but losing key rivets (e.g., those on the wings, analogous to key species) or many rivets threatens the ecosystem.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-36","question":"David Tilman's long-term ecosystem experiments with outdoor plots found that plots with more species:","options":["Always had lower productivity","Were invaded more easily by alien species","Showed less year-to-year variation in total biomass","Showed greater year-to-year variation in total biomass"],"answer":2,"explanation":"Tilman found that increased diversity contributed to higher productivity and less year-to-year variation in total biomass, supporting the idea that rich biodiversity brings stability.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-37","question":"The Mediterranean orchid Ophrys gets pollinated by a bee because:","options":["It rewards the bee with large amounts of nectar and pollen","The female bee lays her eggs inside the flower's ovary","A petal mimics the female bee, and males pseudocopulate with it","It is wind-pollinated, and the bee only accidentally touches it"],"answer":2,"explanation":"Ophrys uses sexual deceit: a petal bears an uncanny resemblance to the female bee in size, colour and markings, so males attempt to mate and transfer pollen.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-38","question":"In primary succession on bare rock, the pioneer species are usually:","options":["Lichens","Large trees","Shrubs","Mosses"],"answer":0,"explanation":"Lichens secrete acids that dissolve rock, helping weathering and soil formation; this paves the way for small plants like bryophytes, and later bigger plants.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-39","question":"How many of the following statements about ecosystems are correct?\n(i) Standing crop is the mass of living material at a trophic level at a particular time.\n(ii) Secondary productivity is the rate of formation of new organic matter by producers.\n(iii) Net primary productivity equals gross primary productivity minus respiration losses.\n(iv) Decomposition is faster in cold and anaerobic conditions.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. Secondary productivity is the rate of formation of new organic matter by consumers, and decomposition is favoured by warm and moist conditions; low temperature and anaerobiosis inhibit it.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-40","question":"Match the organism with its response to stress.\nList I: (A) Kangaroo rat (B) Many desert plants (CAM) (C) Zooplankton in lakes and ponds (D) Bears\nList II: (1) Enter diapause, a stage of suspended development (2) Hibernate during winter (3) Meets water needs through internal fat oxidation and concentrates urine (4) Stomata remain closed during the day","options":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":2,"explanation":"The kangaroo rat of North American deserts survives on metabolic water and concentrated urine; CAM plants open their stomata only at night; zooplankton undergo diapause; bears escape winter by hibernation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-41","question":"Assertion (A): Very small animals are rarely found in polar regions.\nReason (R): Small animals have a larger surface area relative to their volume, so they lose body heat very fast when it is cold.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: small animals would have to spend a lot of energy generating body heat through metabolism, which is why very small animals are rare in polar regions.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-42","question":"In a food chain, tertiary consumers obtain 15 J of energy. Following the 10% law, how much energy was available at the producer level?","options":["1,500 J","150 J","1,50,000 J","15,000 J"],"answer":3,"explanation":"Producer → primary → secondary → tertiary consumer is three transfers, each passing on 10%: producer energy = 15 × 10 × 10 × 10 = 15,000 J.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-43","question":"According to NCERT, all of the following became extinct in recent times (the last 500 years or so) EXCEPT:","options":["Thylacine (Tasmanian wolf)","Dodo of Mauritius","Indian one-horned rhino","Quagga of South Africa"],"answer":2,"explanation":"The dodo, quagga, thylacine, Steller's sea cow and three subspecies of tiger (Bali, Javan, Caspian) are recent extinctions. The Indian rhinoceros still survives.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-44","question":"How many of the following statements about global biodiversity are correct?\n(i) More than 70% of all the species recorded are animals, while plants make up no more than 22%.\n(ii) Among animals, insects are the most species-rich group, making up more than 70% of the total.\n(iii) Robert May estimated global species diversity at about 7 million.\n(iv) India has more than 50,000 genetically different strains of rice and 1,000 varieties of mango.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT facts; out of every 10 animals on the planet, about 7 are insects.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-45","question":"How many of the following statements about ecological pyramids are correct?\n(i) The pyramid of energy can be inverted in some aquatic ecosystems.\n(ii) In most ecosystems all the pyramids, of number, energy and biomass, are upright.\n(iii) Ecological pyramids accommodate food webs.\n(iv) Saprophytes are given a definite place in ecological pyramids.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only (ii) is correct. The pyramid of energy is always upright; ecological pyramids assume a simple food chain and do not accommodate food webs; and saprophytes are given no place in them.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-ecology-environment-46", "question": "In general, species diversity is greatest:", "options": ["In temperate regions", "Near the poles", "In the tropics", "On high mountain tops"], "answer": 2, "explanation": "Species diversity generally decreases as we move away from the equator towards the poles; tropical latitudes have the greatest species richness.", "difficulty": "easy", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-47","question":"In an aquatic ecosystem such as a pond, the main producers are:","options":["Herbivorous fishes and tadpoles","Phytoplankton, algae and higher aquatic plants","Bacteria and fungi decomposing the bottom sediment","Zooplankton feeding on algae"],"answer":1,"explanation":"In aquatic ecosystems the producers are phytoplankton, some algae and the higher plants; zooplankton are consumers and bacteria and fungi are decomposers.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-ecology-environment-48", "question": "Which pair of processes DECREASES the density of a population?", "options": ["Natality and immigration", "Immigration and mortality", "Natality and emigration", "Mortality and emigration"], "answer": 3, "explanation": "Population density rises with natality (births) and immigration and falls with mortality (deaths) and emigration.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-49", "question": "The association between fungi and the roots of higher plants, in which the fungi help absorb nutrients and the plant provides carbohydrates, is called:", "options": ["Mycorrhiza", "Brood parasitism", "Lichen", "Amensalism"], "answer": 0, "explanation": "Mycorrhizae are mutualistic associations between fungi and the roots of higher plants. Lichens are mutualism between a fungus and photosynthesising algae or cyanobacteria.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-50", "question": "Vertical distribution of different species occupying different levels in an ecosystem, with trees at the top, shrubs below and herbs and grasses at the bottom, is called:", "options": ["Species–area relationship", "Succession", "Biomagnification", "Stratification"], "answer": 3, "explanation": "Stratification is the vertical distribution of species at different levels, for example trees, then shrubs, then herbs and grasses in a forest.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-51", "question": "The term 'biodiversity' was popularised by the sociobiologist:", "options": ["Paul Ehrlich", "Edward Wilson", "Alexander von Humboldt", "Robert May"], "answer": 1, "explanation": "Edward Wilson popularised the term biodiversity to describe the combined diversity at all levels of biological organisation. Paul Ehrlich proposed the rivet popper hypothesis, and Humboldt studied species–area relationships.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-52", "question": "A country with deserts, rain forests, mangroves, coral reefs, wetlands, estuaries and alpine meadows, like India, compared with a Scandinavian country like Norway, has a greater:", "options": ["Genetic diversity", "Species diversity only within a single field", "Number of polyploid species", "Ecological diversity"], "answer": 3, "explanation": "Diversity at the ecosystem level is ecological diversity; India, with its many ecosystem types, has greater ecological diversity than Norway.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-53","question":"In Australia, the prickly pear cactus, introduced in the early 1920s, spread rapidly over millions of hectares of rangeland. It was finally brought under control by:","options":["Introducing goats to browse the cactus","A cactus-feeding moth from its native habitat","Aerial spraying of the herbicide 2,4-D over it","Repeated controlled burning of rangeland"],"answer":1,"explanation":"The invasive prickly pear was controlled only after a cactus-feeding predator (a moth) from its natural habitat was introduced, showing how predators keep prey populations in check; biological control methods are based on this.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-54","question":"MacArthur showed that five closely related species of warblers living on the same tree could avoid competition and coexist because of:","options":["Mutualism, each warbler helping the others find food","Different foraging behaviour (resource partitioning)","Commensalism with the tree, which gave them shelter","Brood parasitism, sharing nests among species"],"answer":1,"explanation":"MacArthur's warblers coexisted because of behavioural differences in foraging, i.e. resource partitioning, which is a mechanism that allows coexistence despite competition.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-ecology-environment-55", "question": "Which kind of detritus decomposes at the SLOWEST rate?", "options": ["Detritus that is warm and moist", "Detritus rich in lignin and chitin", "Detritus rich in nitrogen", "Detritus rich in water-soluble substances like sugars"], "answer": 1, "explanation": "Decomposition is slower when detritus is rich in lignin and chitin, and quicker when it is rich in nitrogen and water-soluble substances like sugars. Warm, moist conditions favour decomposition.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-56","question":"Rauwolfia vomitoria growing in different Himalayan ranges shows genetic variation in the potency and concentration of the active chemical:","options":["Ricin","Morphine","Reserpine","Artemisinin"],"answer":2,"explanation":"Rauwolfia vomitoria shows genetic diversity in the potency and concentration of reserpine across Himalayan ranges, an example of diversity at the genetic level.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-ecology-environment-57", "question": "In the species–area relationship, the regression coefficient Z for very large areas such as entire continents is found to be much steeper, in the range of:", "options": ["0.01 to 0.05", "2.0 to 3.0", "0.1 to 0.2", "0.6 to 1.2"], "answer": 3, "explanation": "For small areas Z lies in the range 0.1–0.2 regardless of taxonomic group or region, but for very large areas like whole continents the slope is much steeper, about 0.6 to 1.2 (e.g. frugivorous birds and mammals of tropical forests: 1.15).", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-58", "question": "NCERT quotes intrinsic rates of natural increase (r) for the Norway rat and the flour beetle. These values are respectively:", "options": ["0.0205 and 0.015", "0.015 and 0.12", "0.12 and 0.015", "1.5 and 12"], "answer": 1, "explanation": "r is 0.015 for the Norway rat and 0.12 for the flour beetle. 0.0205 was the r value for the human population of India in 1981.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-59","question":"Calotropis growing in abandoned fields is not browsed by cattle or goats because it:","options":["Is camouflaged among dry grasses","Bears thick, sharp thorns on its stems","Has hairy leaves that cattle cannot chew","Produces poisonous cardiac glycosides"],"answer":3,"explanation":"Calotropis produces highly poisonous cardiac glycosides, a chemical defence against herbivores. Thorns are the defence of Acacia and cactus.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-60","question":"How many of the following are among the hypotheses proposed to explain the greater biological diversity of the tropics?\n(i) Tropical latitudes have remained relatively undisturbed for millions of years, giving a long evolutionary time for species diversification.\n(ii) Tropical environments are less seasonal and relatively more constant and predictable, promoting niche specialisation.\n(iii) There is more solar energy available in the tropics, contributing to higher productivity.\n(iv) Unlike temperate regions, the tropics were not subjected to frequent glaciations in the past.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Speciation is a function of time, and the tropics escaped the frequent glaciations of temperate regions, giving a long undisturbed period; tropical environments are also constant and predictable, and more solar energy means higher productivity.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-ecology-environment-61", "question": "Match the reason for conserving biodiversity with its description.\nList I: (A) Narrowly utilitarian (B) Broadly utilitarian (C) Ethical (D) Bioprospecting\nList II: (1) Every species has an intrinsic value and we have a moral duty to care for it (2) Exploring molecular, genetic and species-level diversity for products of economic importance (3) Direct economic benefits such as food, firewood, fibre and medicines (4) Ecosystem services such as oxygen production and pollination", "options": ["A-3, B-4, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2"], "answer": 0, "explanation": "Direct products are the narrowly utilitarian argument; ecosystem services such as the Amazon producing about 20% of the earth's oxygen are broadly utilitarian; intrinsic value is the ethical argument; bioprospecting looks for economically useful products in biodiversity.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-62", "question": "Assertion (A): Humus serves as a reservoir of nutrients in the soil.\nReason (R): Humus is colloidal and highly resistant to microbial action, so it undergoes decomposition at an extremely slow rate.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Humus is a dark, amorphous, colloidal substance that decomposes very slowly; it is later degraded by some microbes, releasing inorganic nutrients by mineralisation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-63", "question": "A population of 1000 individuals had 60 births, 40 deaths, 10 immigrants and 5 emigrants in one year. Using Nₜ₊₁ = Nₜ + [(B + I) − (D + E)], the population after one year is:", "options": ["1025", "1015", "1070", "1035"], "answer": 0, "explanation": "Nₜ₊₁ = 1000 + [(60 + 10) − (40 + 5)] = 1000 + (70 − 45) = 1025. Ignoring migration gives 1020, and adding emigrants instead of subtracting gives 1035.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-64", "question": "In an ecosystem, photosynthetically active radiation (PAR) is 40% of the incident solar radiation and plants capture 5% of the PAR. If 10⁶ J of solar radiation falls on the area, the energy captured by plants (gross primary production) is:", "options": ["2,000 J", "50,000 J", "40,000 J", "20,000 J"], "answer": 3, "explanation": "PAR = 40% of 10⁶ J = 4 × 10⁵ J. Plants capture 5% of this: 0.05 × 4 × 10⁵ = 2 × 10⁴ = 20,000 J. Taking 5% of the total incident radiation gives the 50,000 J trap. NCERT notes PAR is less than 50% of incident radiation and plants capture only 2–10% of it.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-65", "question": "Match the example with the type of interaction.\nList I: (A) Lichen (B) Cuscuta on hedge plants (C) Barnacles growing on the back of a whale (D) Goats and the Abingdon tortoise on the Galapagos\nList II: (1) Commensalism (2) Competition (3) Mutualism (4) Parasitism", "options": ["A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "A lichen is a fungus–alga mutualism; Cuscuta is a parasitic plant; barnacles benefit from the whale without affecting it (commensalism); the Abingdon tortoise became extinct within a decade of goats arriving, owing to the goats' greater browsing efficiency (competition).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-ecology-environment-66", "question": "All of the following are defences of prey against predation EXCEPT:", "options": ["Thorns in Acacia and cactus", "The Monarch butterfly being distasteful because of a chemical acquired from a poisonous weed eaten as a caterpillar", "A fungus living with an alga to form a lichen", "Cryptic colouration (camouflage) in some insects and frogs"], "answer": 2, "explanation": "Camouflage, distastefulness (the Monarch butterfly) and thorns are anti-predator or anti-herbivore defences. A lichen is a mutualistic association, not a defence against predation.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-67","question":"How many of the following statements about decomposition are correct?\n(i) Detritivores such as earthworms break down detritus into smaller particles in fragmentation.\n(ii) In leaching, water-soluble inorganic nutrients go down into the soil horizon and get precipitated as unavailable salts.\n(iii) Humification leads to the accumulation of a dark-coloured amorphous substance called humus.\n(iv) Mineralisation is the degradation of detritus by bacterial and fungal enzymes into simpler inorganic substances.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) describes catabolism; mineralisation is the release of inorganic nutrients when humus is further degraded by some microbes.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-ecology-environment-68", "question": "Assertion (A): Gause's competitive exclusion principle states that two closely related species competing for the same resources cannot coexist indefinitely, and the competitively inferior one will eventually be eliminated.\nReason (R): Competition occurs only between closely related species.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true. R is false: totally unrelated species can also compete for the same resource, such as flamingoes and resident fishes competing for zooplankton in some shallow South American lakes.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-69","question":"How many of the following statements about biodiversity loss are correct?\n(i) The IUCN Red List (2004) documents the extinction of 784 species in the last 500 years.\n(ii) These include 338 vertebrates, 359 invertebrates and 87 plants.\n(iii) Presently more than 15,500 species worldwide are facing the threat of extinction.\n(iv) Current species extinction rates are estimated to be about 10 to 20 times faster than in pre-human times.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct NCERT data. (iv) is wrong: the current 'sixth extinction' is estimated to be 100 to 1000 times faster than in pre-human times, with human activities responsible.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-ecology-environment-70", "question": "Arrange the following in DECREASING order of the number of bird species found there: (i) New York (ii) Colombia (iii) Greenland (iv) India", "options": ["(ii), (i), (iv), (iii)", "(ii), (iv), (i), (iii)", "(iv), (ii), (i), (iii)", "(ii), (iv), (iii), (i)"], "answer": 1, "explanation": "Colombia, near the equator, has nearly 1400 bird species; India has more than 1200; New York at 41° N has 105; Greenland at 71° N has only 56. This illustrates the latitudinal gradient in diversity.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-ecology-environment-71","question":"Eichhornia crassipes (water hyacinth), one of the world's most problematic aquatic weeds, is also called:","options":["Terror of Bengal","Lungs of the planet","Congress grass","Living fossil"],"answer":0,"explanation":"Water hyacinth, nicknamed the 'Terror of Bengal', grows abundantly in eutrophic water bodies and upsets the ecosystem dynamics. 'Congress grass' is a common name for Parthenium.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-72","question":"The thickness of ozone in a column of air from the ground to the top of the atmosphere is measured in:","options":["Decibels","Lux","Millibars (pressure)","Dobson units"],"answer":3,"explanation":"Ozone thickness is expressed in Dobson units (DU). Decibels measure sound level.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-73","question":"To estimate tiger numbers in national parks and tiger reserves, census counts are often based on:","options":["Pug marks and fecal pellets","Percent cover of the forest","Direct counts of every tiger","Total biomass of the tigers"],"answer":0,"explanation":"Tigers are hard to count directly, so pug marks and fecal pellets are used as indirect measures of population size.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-ecology-environment-74","question":"Cattle egrets forage close to grazing cattle, catching insects that the cattle stir up from the vegetation. This interaction is an example of:","options":["Mutualism","Commensalism","Parasitism","Amensalism"],"answer":1,"explanation":"The egret benefits while the cattle are neither helped nor harmed, so this is commensalism (+, 0).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-75","question":"Which organisms breed only once in their lifetime?","options":["Most birds and mammals","Oysters and pelagic fishes","Pacific salmon and bamboo","Humans and elephants"],"answer":2,"explanation":"Pacific salmon and bamboo breed once and die, whereas most birds and mammals breed many times. Oysters and pelagic fishes are examples of species that produce many small offspring.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-76","question":"Which of the following is an ectoparasite?","options":["The human liver fluke","Copepods on marine fish","Plasmodium inside red blood cells","A tapeworm in the intestine"],"answer":1,"explanation":"Ectoparasites feed on the external surface of the host, like lice on humans, ticks on dogs and copepods on marine fish. The other three live inside the host's body.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-77","question":"Ozone in the lower atmosphere (troposphere) is called 'bad' ozone because it:","options":["Harms plants and animals","Absorbs ultraviolet radiation from the sun","Is broken down by CFCs","Is measured in Dobson units"],"answer":0,"explanation":"Tropospheric ozone harms plants and animals. 'Good' ozone in the stratosphere shields us by absorbing UV radiation.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-78","question":"Eutrophication refers to:","options":["Increase in the salinity of coastal sea water","Removal of nutrients from a lake by fish and birds","Acidification of lakes by acid rain","Natural ageing of a lake by nutrient enrichment"],"answer":3,"explanation":"Eutrophication is the natural ageing of a lake as nutrients build up. Human pollutants such as sewage and fertiliser run-off speed it up, which is called cultural or accelerated eutrophication.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-79","question":"Jhum cultivation, practised in the north-eastern states of India, is:","options":["Terrace farming on hill slopes","Hydroponics","Slash-and-burn agriculture","Integrated organic farming"],"answer":2,"explanation":"In jhum, trees are cut and burnt, the ash fertilises the land for farming, and the plot is later abandoned. Today the gaps between cultivation cycles are too short for the land to recover.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-ecology-environment-80","question":"The human liver fluke, a trematode, needs two intermediate hosts to complete its life cycle. These are:","options":["A mosquito and a pig","A cow and a pig","A snail only","A snail and a fish"],"answer":3,"explanation":"The liver fluke completes its life cycle through a snail and a fish. Such complex life cycles with intermediate hosts are common in endoparasites.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-81","question":"When all the starfish Pisaster were removed from an enclosed intertidal area on the American Pacific Coast, what happened within a year?","options":["Invertebrate diversity increased sharply without the predator","Over 10 invertebrate species went extinct through competition","Only the barnacles, its main prey, disappeared","The number of species did not change at all"],"answer":1,"explanation":"The predator had been keeping competing prey in check. Without it, competition among the prey drove more than 10 invertebrate species extinct, which shows how predators help maintain species diversity.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-82","question":"In a laboratory population of 200 fruit flies, 30 died during a week. What was the death rate during that week?","options":["0.30 individuals per fruit fly per week","6.67 individuals per fruit fly per week","0.15 individuals per fruit fly per week","30 individuals per week per fruit fly"],"answer":2,"explanation":"Death rate = number of deaths / population size = 30 / 200 = 0.15 individuals per fruit fly per week.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-83","question":"In 1981 the intrinsic rate of natural increase (r) for the human population of India was 0.0205 per year. Using dN/dt = rN, what is the instantaneous growth rate of a population of 1,000,000 with this r?","options":["20,500 individuals per year","2,050 individuals per year","205,000 individuals per year","48,780 individuals per year"],"answer":0,"explanation":"dN/dt = rN = 0.0205 × 1,000,000 = 20,500 individuals per year.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-84","question":"Hydrarch succession and xerarch succession both lead towards:","options":["Mesic conditions","Hydric conditions","Xeric conditions","Saline conditions"],"answer":0,"explanation":"Succession on water (hydrarch) and on dry areas (xerarch) both move towards medium water (mesic) conditions.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-85","question":"In a terrestrial ecosystem, a much larger fraction of the energy flows through the:","options":["Grazing food chain","Detritus food chain","Parasitic food chain","Producers only, with no transfer"],"answer":1,"explanation":"In terrestrial ecosystems most energy flows through the detritus food chain, whereas in aquatic ecosystems the grazing food chain is the main route.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-86","question":"How many species have disappeared in the last twenty years alone?","options":["7","27","270","784"],"answer":1,"explanation":"27 species have disappeared in the last twenty years. The figure 784 is the total number of extinctions documented over the last 500 years in the IUCN Red List (2004).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-87","question":"High doses of UV-B radiation cause inflammation of the cornea, a condition called:","options":["Cataract","Glaucoma","Snow-blindness","Night blindness"],"answer":2,"explanation":"UV-B inflames the cornea, causing snow-blindness, and can also cause cataract. UV-B damages DNA and may cause mutation and skin ageing.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-88","question":"Polyblend, a fine powder of recycled modified plastic that is mixed with bitumen to lay roads, was developed by:","options":["Ramesh Chandra Dagar","Amrita Devi Bishnoi","Sunderlal Bahuguna (Chipko)","Ahmed Khan, Bangalore"],"answer":3,"explanation":"Ahmed Khan, a plastic sack manufacturer in Bangalore, developed polyblend; mixed with bitumen, it improves the water-repellent property of roads. Ramesh Chandra Dagar promoted organic farming in Sonipat, Haryana.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-89","question":"The National Forest Policy (1988) of India recommends a forest cover of:","options":["33 per cent for the plains and 67 per cent for the hills","67 per cent for the plains and 33 per cent for the hills","19.4 per cent for both plains and hills","50 per cent for both plains and hills"],"answer":0,"explanation":"The policy recommends 33% forest cover in the plains and 67% in the hills. Actual forest cover in India had fallen to about 19.4% by the end of the twentieth century.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-90","question":"A population grows exponentially according to Nt = N0 e^(rt). If N0 = 100, r = 0.1 per year and t = 10 years, the population after 10 years will be about (take e = 2.718):","options":["200","272","110","1,000"],"answer":1,"explanation":"rt = 0.1 × 10 = 1, so Nt = 100 × e^1 = 100 × 2.718, which is about 272.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-91","question":"How many of the following statements about the price tags on ecosystem services estimated by Robert Constanza and colleagues are correct?\n(i) The average price tag is about US $33 trillion a year.\n(ii) This is nearly twice the global gross national product (about US $18 trillion).\n(iii) Soil formation accounts for about 50 per cent of the total cost.\n(iv) Recreation and nutrient cycling each contribute less than 10 per cent.\n(v) Climate regulation and habitat for wildlife each contribute about 30 per cent.","options":["Only four","Only three","Only two","All five"],"answer":0,"explanation":"Statements (i) to (iv) are correct. Climate regulation and habitat for wildlife each contribute only about 6 per cent.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-92","question":"Match the group with the percentage of its species in the world that face the threat of extinction.\nList I: (A) Birds (B) Mammals (C) Amphibians (D) Gymnosperms\nList II: (1) 31% (2) 32% (3) 23% (4) 12%","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"About 12% of bird species, 23% of mammal species, 32% of amphibian species and 31% of gymnosperm species face the threat of extinction.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-93","question":"Arrange the stages of hydrarch succession in the correct sequence.\n(i) Rooted hydrophytes (ii) Phytoplankton (iii) Sedges and grasses (iv) Free-floating angiosperms (v) Trees (climax forest)","options":["(ii), (i), (iv), (iii), (v)","(ii), (iv), (i), (iii), (v)","(iv), (ii), (i), (iii), (v)","(ii), (iv), (iii), (i), (v)"],"answer":1,"explanation":"Small phytoplankton are the pioneers. They are replaced in turn by free-floating angiosperms, rooted hydrophytes, sedges and grasses, and finally trees, giving a climax forest.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-94","question":"Assertion (A): Secondary succession is faster than primary succession, and the climax is reached more quickly.\nReason (R): In secondary succession, soil or sediment is already present.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. Secondary succession starts where life once existed (abandoned farmland, burned or cut forests, flooded land), and because soil is already present, R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-95","question":"From the following list, how many are adaptations commonly seen in parasites?\nLoss of unnecessary sense organs, adhesive organs or suckers to cling to the host, loss of the digestive system, high reproductive capacity, strong locomotory organs for active hunting","options":["Two","Three","Five","Four"],"answer":3,"explanation":"The first four are typical parasite adaptations. Strong locomotory organs for active hunting are a predator feature, not a parasite one.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-96","question":"From the following list, how many are chemicals produced by plants as defences against grazers and browsers?\nNicotine, caffeine, quinine, strychnine, opium, cardiac glycosides, chlorophyll, cellulose","options":["Four","Five","Six","Seven"],"answer":2,"explanation":"Nicotine, caffeine, quinine, strychnine, opium and the cardiac glycosides of Calotropis are defensive chemicals. Chlorophyll is a photosynthetic pigment, and cellulose is a structural polysaccharide.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-97","question":"How many of the following statements about the Air Act and noise pollution in India are correct?\n(i) The Air (Prevention and Control of Pollution) Act came into force in 1981.\n(ii) It was amended in 1987 to include noise as an air pollutant.\n(iii) A sound level of 150 dB or more, as at the take-off of a jet plane or rocket, may damage the eardrums and permanently impair hearing.\n(iv) Noise can cause sleeplessness, increased heart beat and altered breathing.\n(v) An electrostatic precipitator is the standard device for removing noise.","options":["Only two","Only four","Only three","All five"],"answer":1,"explanation":"Statements (i) to (iv) are correct. An electrostatic precipitator removes particulate matter from exhaust, not noise.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-98","question":"Assertion (A): The interaction between the clown fish and the sea anemone is an example of commensalism.\nReason (R): The clown fish gets protection from predators among the stinging tentacles, and the anemone does not appear to derive any benefit.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is NOT the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both statements are true. One partner benefits and the other is unaffected, which is the definition of commensalism, so R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-99","question":"How many of the following statements about the carbon cycle are correct?\n(i) Carbon makes up about 49 per cent of the dry weight of organisms.\n(ii) About 71 per cent of the total carbon is found dissolved in the oceans.\n(iii) About 4 × 10^13 kg of carbon is fixed in the biosphere through photosynthesis every year.\n(iv) The oceanic reservoir regulates the amount of CO2 in the atmosphere.\n(v) The carbon cycle is a sedimentary cycle with its reservoir in the earth's crust.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"Statements (i) to (iv) are correct. The carbon cycle is a gaseous cycle, with its reservoir in the atmosphere and the oceans; phosphorus is the sedimentary example.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-100","question":"Nuclear waste, after pre-treatment, should be stored in suitably shielded containers and buried within rocks at a depth of about:","options":["5 m","50 m","5,000 m","500 m"],"answer":3,"explanation":"Nuclear waste is buried within rocks about 500 m below the Earth's surface, because its radiation is extremely damaging to living things.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-ecology-environment-101","question":"A population grows logistically with r = 0.1 per year and carrying capacity K = 800. What is the MAXIMUM rate of increase (dN/dt) this population can reach?","options":["10 individuals per year","20 individuals per year","40 individuals per year","80 individuals per year"],"answer":1,"explanation":"rN(K − N)/K is greatest at N = K/2 = 400, giving 0.1 × 400 × (400/800) = 20 per year. 40 forgets the (K − N)/K factor, and 80 is rK.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-102","question":"A population of 1,000 grows to 1,100 in one year. During the year there were 150 births, 70 deaths and 30 immigrants. How many individuals emigrated?","options":["10","30","50","110"],"answer":0,"explanation":"Nt+1 = Nt + [(B + I) − (D + E)], so 1100 = 1000 + (150 + 30) − (70 + E), which gives E = 10.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-103","question":"NCERT gives the intrinsic rate of natural increase (r) of India's population in 1981 as 0.0205 per year. If the population grew exponentially at this rate, about how long would it take to double?","options":["About 20 years","About 49 years","About 100 years","About 34 years"],"answer":3,"explanation":"For exponential growth the doubling time is ln 2 / r = 0.693 / 0.0205 ≈ 34 years. 49 years is 1/r, which forgets the ln 2 factor.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-104","question":"Match the population interaction with its effect on species A and species B.\nList I: (A) Amensalism (B) Commensalism (C) Competition (D) Parasitism\nList II: (1) + and − (2) − and − (3) + and 0 (4) − and 0","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Amensalism harms one and leaves the other unaffected (−, 0); commensalism benefits one (+, 0); competition harms both (−, −); parasitism benefits the parasite and harms the host (+, −).","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-105","question":"NCERT cites which example to show that competition can occur even between totally unrelated species?","options":["Cattle egrets and grazing cattle feeding on the same insects","Flamingoes and resident fishes competing for zooplankton","Clown fish and sea anemone sharing the same stinging tentacles","Koel and crow sharing the same nest during the breeding season"],"answer":1,"explanation":"In some shallow South American lakes, visiting flamingoes and resident fishes compete for their common food, the zooplankton. The egret is commensalism, the clown fish is commensalism and the koel is brood parasitism.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-106","question":"The Abingdon tortoise of the Galapagos Islands became extinct within a decade after goats were introduced, mainly because the goats:","options":["Preyed heavily on the tortoise hatchlings and eggs","Spread a parasite that killed most of the tortoises","Trampled the tortoise eggs buried in the sand","Browsed vegetation more efficiently than tortoises"],"answer":3,"explanation":"NCERT attributes the extinction to the greater browsing efficiency of the goats, an example of competition for the same resource rather than predation or disease.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-107","question":"The monarch butterfly is highly distasteful to its predators (birds) because:","options":["It takes in a chemical from a poisonous weed as a caterpillar","It synthesises cardiac glycosides itself in its wing scales as an adult","Its bright colours carry toxic pigments that it makes in its gut","It mimics another butterfly that happens to be poisonous to birds"],"answer":0,"explanation":"The monarch's distastefulness comes from a special chemical it takes in as a caterpillar by feeding on a poisonous weed; it does not make the toxin itself.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-108","question":"Which pair of organisms produces a large number of small-sized offspring?","options":["Birds and mammals","Pacific salmon fish and bamboo","Elephants and whales","Oysters and pelagic fishes"],"answer":3,"explanation":"NCERT contrasts oysters and pelagic fishes (many small offspring) with birds and mammals (few, large offspring). Pacific salmon and bamboo are examples of breeding only once.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-ecology-environment-109","question":"An area has one huge banyan tree with a very large canopy and 200 Parthenium plants. Why is the plain number of individuals a poor measure of their population sizes here?","options":["Banyan is a long-lived perennial, while Parthenium is an annual weed","Parthenium is an alien species, so its individuals cannot be counted","Plant populations can be estimated only by indirect signs like pug marks","Counting ignores size; percent cover or biomass is more meaningful"],"answer":3,"explanation":"Counting would make Parthenium seem far more important than the single huge banyan; percent cover or biomass reflects their actual role better.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-110","question":"When absolute numbers are not required, a measure such as the number of fish caught per trap gives the:","options":["Relative density of the population","Absolute density of the population","Intrinsic rate of natural increase","Carrying capacity of the habitat"],"answer":0,"explanation":"Fish caught per trap does not give the actual number of fish but is a good index of relative population density, which is often enough for ecological studies.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-ecology-environment-111","question":"Match the step of decomposition with its description.\nList I: (A) Fragmentation (B) Leaching (C) Humification (D) Mineralisation\nList II: (1) Water-soluble inorganic nutrients go down into the soil and precipitate as unavailable salts (2) Detritivores break down detritus into smaller particles (3) Humus is degraded further, releasing inorganic nutrients (4) A dark, amorphous substance resistant to microbial action accumulates","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-4, C-1, D-3"],"answer":0,"explanation":"Fragmentation is by detritivores, leaching washes nutrients into the soil, humification forms humus, and mineralisation releases inorganic nutrients from humus.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-112","question":"Which combination would lead to the FASTEST decomposition of detritus?","options":["Lignin- and chitin-rich detritus in warm, moist soil","Nitrogen- and sugar-rich detritus in cold, waterlogged soil","Nitrogen- and sugar-rich detritus in warm, moist soil","Lignin-rich detritus in cold, anaerobic soil"],"answer":2,"explanation":"Decomposition is quicker for detritus rich in nitrogen and water-soluble substances like sugars, and is favoured by warm, moist conditions. Lignin, chitin, low temperature and anaerobiosis all slow it.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-113","question":"How many of the following are limitations of ecological pyramids as stated by NCERT?\n(i) They do not take into account the same species belonging to two or more trophic levels.\n(ii) They assume a simple food chain, which almost never exists in nature.\n(iii) They do not accommodate a food web.\n(iv) Saprophytes are not given any place in them.\n(v) The pyramid of energy can be inverted in some ecosystems.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i)–(iv) are the limitations listed by NCERT. The pyramid of energy is always upright, so (v) is false.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-114","question":"Which sequence correctly shows the stages of succession on bare rock (xerarch)?","options":["Lichens → bryophytes → herbs → shrubs → trees","Bryophytes → lichens → herbs → shrubs → trees","Phytoplankton → lichens → shrubs → herbs → trees","Lichens → herbs → bryophytes → trees → shrubs"],"answer":0,"explanation":"Lichens secrete acids that dissolve rock and start soil formation; small bryophytes follow, then herbs (and grasses), shrubs and finally trees in a stable climax.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-115","question":"Assertion (A): Gaseous exchange of phosphorus between organisms and their environment is negligible.\nReason (R): The natural reservoir of phosphorus is rock, and there is no respiratory release of phosphorus into the atmosphere.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Unlike carbon, phosphorus has no significant gaseous form: it comes from rock and is not released in respiration, so gaseous exchange is negligible. R explains A.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-116","question":"India has only about ____ of the world's land area, but its share of global species diversity is about ____.","options":["8.1%; 2.4%","2.4%; 8.1%","12%; 8.1%","2.4%; 12%"],"answer":1,"explanation":"India covers 2.4% of the world's land area and holds about 8.1% of global species diversity, making it one of the 12 megadiversity countries.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-ecology-environment-117","question":"Using the variation of species richness with latitude, Robert May estimated the global species diversity at about:","options":["1.5 million","70 million","20 million","7 million"],"answer":3,"explanation":"Robert May's conservative estimate is about 7 million species. About 1.5 million species have been described so far, the trap figure.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-118","question":"According to NCERT, the number of fungal species in the world is:","options":["More than fishes, amphibians, reptiles and mammals combined","Less than the total number of mammal species in the world","About equal to the total number of fish species in the world","More than the total number of insect species in the world"],"answer":0,"explanation":"NCERT points out that fungal species outnumber the fishes, amphibians, reptiles and mammals put together, though insects remain the richest group.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-119","question":"In a region where the species–area relationship has Z = 0.2, a survey of a small area finds 40 species. About how many species would be expected in an area 32 times larger?","options":["48","64","80","160"],"answer":2,"explanation":"S = CA^Z, so S₂/S₁ = (32)^0.2 = 2, giving 40 × 2 = 80 species. 48 comes from wrongly multiplying by 1 + Z.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-120","question":"NCERT notes a much steeper slope (Z) for frugivorous birds and mammals in the tropical forests of different continents. The value quoted is:","options":["0.15","0.6","1.15","1.2"],"answer":2,"explanation":"For frugivorous birds and mammals in tropical forests of different continents, Z is 1.15. For small areas Z is 0.1–0.2, and for very large areas 0.6–1.2.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-121","question":"The IUCN Red List (2004) documents 784 extinctions in the last 500 years. Which group accounts for the LARGEST share of them?","options":["Vertebrates","Invertebrates","Flowering plants","Fungi"],"answer":1,"explanation":"Of the 784 extinctions, 359 are invertebrates, 338 vertebrates and 87 plants.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-122","question":"The African catfish Clarias gariepinus, introduced for aquaculture, poses a threat to:","options":["Mangrove forests of the Sundarbans","Indigenous catfishes of Indian rivers","Coral reefs of the Lakshadweep islands","Cichlid fishes of Lake Victoria"],"answer":1,"explanation":"The illegal introduction of the African catfish is a threat to the indigenous catfishes of our rivers. The cichlids of Lake Victoria were wiped out by the Nile perch.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-123","question":"When a host fish species becomes extinct, the unique set of parasites living only on it also dies out. This cause of biodiversity loss is called:","options":["Over-exploitation","Habitat fragmentation","Co-extinction","Alien species invasion"],"answer":2,"explanation":"When a species becomes extinct, plant and animal species obligately associated with it, such as its unique parasites, also become extinct: co-extinction.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-124","question":"Arguments for conserving biodiversity based on ecosystem services such as oxygen production, pollination and aesthetic pleasure fall under the:","options":["Narrowly utilitarian argument","Ethical argument","Bioprospecting argument","Broadly utilitarian argument"],"answer":3,"explanation":"The broadly utilitarian argument rests on ecosystem services (the Amazon produces about 20% of the earth's oxygen), whereas the narrowly utilitarian one rests on direct products like food, timber and medicines.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-125","question":"How many of the following statements about biodiversity hotspots are correct?\n(i) Their total number in the world is 34.\n(ii) Three of them, Western Ghats and Sri Lanka, Indo-Burma and Himalaya, cover India's exceptionally high biodiversity regions.\n(iii) Together they cover less than 2 per cent of the earth's land area.\n(iv) Strict protection of hotspots could reduce the ongoing mass extinctions by almost 30 per cent.\n(v) They are regions of high species richness but low endemism.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i)–(iv) are correct. Hotspots are defined by high species richness AND high endemism, so (v) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-126","question":"In the classic biomagnification example, DDT rises from 0.003 ppb in water to 25 ppm in fish-eating birds. By roughly what factor has its concentration increased?","options":["About 8,000 times","About 25,000 times","About 8 billion times","About 8 million times"],"answer":3,"explanation":"25 ppm = 25,000 ppb, and 25,000 ÷ 0.003 ≈ 8.3 × 10⁶. Forgetting to convert ppm to ppb gives about 8,000 times.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-127","question":"High concentrations of DDT cause a decline in fish-eating bird populations mainly because DDT:","options":["Kills the birds directly by blocking their respiration and nerves","Disturbs calcium metabolism, so eggshells thin and break early","Makes the birds sterile by destroying their gonads completely","Reduces fish populations so much that the birds starve to death"],"answer":1,"explanation":"DDT disturbs calcium metabolism in birds, causing thinning of the eggshell and its premature breaking, which leads to population decline.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-ecology-environment-128","question":"Without the greenhouse effect, the average temperature of the earth's surface would be about:","options":["−18 °C","0 °C","15 °C","+33 °C"],"answer":0,"explanation":"Greenhouse gases keep the average surface temperature at about 15 °C; without them it would be a chilly −18 °C. 33 °C is the difference, not the temperature.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-ecology-environment-129","question":"Which pair consists of two examples of commensalism?","options":["Lichens, and mycorrhizae on plant roots","Cuscuta on hedge plants, and the koel laying eggs in a crow's nest","An orchid growing on a mango branch, and barnacles on the back of a whale","Clown fish living among sea anemone tentacles, and Balanus overgrowing Chthamalus"],"answer":2,"explanation":"The orchid and the barnacles benefit while the mango and the whale are unaffected. Lichens and mycorrhizae are mutualism, Cuscuta and koel are parasitism, and Balanus–Chthamalus is competition.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-130","question":"Which statement about the capture of solar energy by plants is correct according to NCERT?","options":["Plants capture about 50% of the incident solar radiation","PAR makes up more than 50% of incident radiation","Plants capture only 2–10% of PAR, yet it sustains all life","Plants capture 10% of the PAR and pass 2% of it on to herbivores"],"answer":2,"explanation":"Less than 50% of the incident radiation is PAR, and plants capture only 2–10% of the PAR; this small fraction sustains all life.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-131","question":"Assertion (A): In an aquatic ecosystem, the grazing food chain is the major conduit for energy flow.\nReason (R): In a terrestrial ecosystem, a much larger fraction of energy flows through the detritus food chain than through the grazing food chain.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true as given in NCERT, but a fact about terrestrial ecosystems cannot explain a fact about aquatic ones.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-132","question":"How many of the following statements about population growth are correct?\n(i) Exponential growth gives a J-shaped curve when N is plotted against time.\n(ii) Logistic growth gives a sigmoid curve.\n(iii) Logistic growth is also called Verhulst–Pearl logistic growth.\n(iv) In logistic growth, dN/dt is maximum when N equals K.\n(v) The logistic model is considered more realistic because resources are finite.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. When N = K, (K − N)/K = 0, so the growth rate is zero, not maximum; it is maximum at N = K/2.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-133","question":"In ecological succession, the entire sequence of communities that successively change in an area, the individual transitional communities, and the final stable community are called respectively:","options":["Seral stages, sere, climax community","Sere, seral stages, climax community","Sere, climax communities, pioneer community","Pioneer stages, seres, seral community"],"answer":1,"explanation":"The whole sequence is the sere (seres), each transitional community is a seral stage, and the final stable community is the climax community.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-ecology-environment-134","question":"Which of the following illustrates SPECIES diversity rather than genetic or ecological diversity?","options":["The Western Ghats having a greater amphibian species diversity than the Eastern Ghats","India having more than 50,000 genetically different strains of rice","Different Himalayan populations of Rauwolfia vomitoria differing in reserpine content","India having deserts, rain forests, mangroves, coral reefs and alpine meadows"],"answer":0,"explanation":"Comparing the number of amphibian species between regions is species diversity. Rice strains and reserpine variation show genetic diversity, and the variety of ecosystems is ecological diversity.","difficulty":"hard","source":"NEET UG"},
];

export default questions;
